      fn get_value(value: &Value) -> Option<GeoPoint> {
          match value {
              Value::Object(obj) => {
                  let lon_op = obj.get("lon").and_then(|x| x.as_f64());
                  let lat_op = obj.get("lat").and_then(|x| x.as_f64());
                  if let (Some(lon), Some(lat)) = (lon_op, lat_op) {
                      return GeoPoint::new(lon, lat).ok();
                  }
                  None
              }
              _ => None,
          }
      }

